INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'Biology', 'Unit 4', 'Molarum Grade 10 — Biology Cell Reproduction', 'Source-grounded Molarum Grade 10 Biology questions for Cell Reproduction.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('c5dd12bd-cd96-404d-8158-b0531fe93790'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'According to Unit 4: Cell Reproduction, what are the main divisions of the cell cycle?', 'Interphase and M phase', 'The cell cycle is commonly divided into a non-dividing interphase (G1, S, G2) and the M phase (mitosis and cytokinesis).', 0),('dfa6b098-96c5-4220-8550-170828231e00'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'What is the main purpose of mitosis?', 'To produce two genetically identical diploid daughter cells', 'Mitosis distributes a complete set of chromosomes to two genetically identical daughter cells, enabling growth and tissue repair.', 1),('593524ec-9e05-4c92-8d6b-a14f3c551029'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'During which phase do sister chromatids separate?', 'Anaphase', 'Sister chromatids separate and move to opposite poles during anaphase.', 2),('d57f14d1-cd7a-4c28-8a57-c74615b24074'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which structure regulates the cell cycle checkpoints and makes key proteins such as cyclins?', 'Cyclins and CDKs', 'Cyclins and cyclin-dependent kinases (CDKs) are key regulators of cell cycle progression and checkpoints.', 3),('21180454-7263-4c8d-8777-985fdf7280fc'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'What is a likely outcome if the cell cycle is not properly regulated?', 'Cancer development due to unchecked cell division', 'Loss of control can lead to uncontrolled cell division and tumor formation (cancer).', 4),('63a41c59-90ab-48e5-8175-d46151a3edc7'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'true_false', 'True or False: A failure to regulate the cell cycle can contribute to cancer.', 'True', 'Unregulated cell cycle progression can lead to uncontrolled growth and tumor formation.', 5),('4a6a6f1e-f15c-4a5c-8cff-17556b0c53c7'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'Name two differences between mitosis and meiosis.', 'Mitosis yields two genetically identical diploid daughter cells; Meiosis yields four genetically diverse haploid cells.', 'Mitosis maintains chromosome number and genetic similarity; meiosis halves the chromosome number and increases genetic variation through recombination.', 6),('09ffabea-c84e-43ac-89c8-1a8124577f9f'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'Explain the relationship between chromosomes and sister chromatids during the cell cycle.', 'A chromosome is a single DNA molecule; after DNA replication, each chromosome consists of two sister chromatids that stay attached at the centromere until anaphase.', 'During S phase, DNA is replicated resulting in sister chromatids; separation occurs in anaphase.', 7),('7878c2d6-018b-4994-847c-ebc2cdd89dce'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'In a cell culture, 60 cells are observed in mitosis out of 800 total cells. Calculate the mitotic index. Provide the method and final unit.', '0.075', 'Mitotic index = number in mitosis / total number of cells. 60/800 = 0.075 (dimensionless).', 8),('11ff358a-17f3-47b0-803d-21a2df028205'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'If a tissue has a cell cycle duration of 24 hours and mitosis lasts 2 hours, what percentage of cells are expected to be in mitosis at any given moment? Express your answer as a percent with two decimal places.', '8.33%', 'Mitotic index ≈ M duration / total cycle duration = 2 / 24 = 0.0833 = 8.33%.', 9),('9eb9bb51-26a9-409e-8b63-8e643a55e6e6'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'During the cell cycle modeling activity, which event marks the onset of mitosis?', 'Prophase: chromosomes condense and become visible', 'Mitosis begins with prophase when chromosomes condense and become visible, signaling the transition from interphase to mitotic stages.', 10),('0e9c1821-3f7b-4712-82f5-ebec592649c2'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which process produces two genetically identical daughter cells?', 'Mitosis', 'Mitosis is the nuclear division that produces two genetically identical somatic cells.', 11),('90879f73-9ce1-4ec4-8d43-f0783c64eb02'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which organelle is primarily responsible for organizing spindle fibers during cell division?', 'Centrosome', 'Centrosomes organize the microtubules that form the spindle apparatus used during chromosome separation.', 12),('dd66bfb8-b879-4075-81f4-1d23bceb9cff'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'During the cell cycle, which phase is when the DNA is replicated?', 'S', 'S phase stands for synthesis, the period when DNA replication occurs before mitosis.', 13),('710f8c69-bf3d-4c4e-8e45-cf944619dd53'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'In a cell cycle model, if G1 lasts 9 h, S lasts 7 h, G2 lasts 4 h, and M lasts 4 h, what is the total cell cycle length in hours?', '24 hours', 'Total cycle length = 9 + 7 + 4 + 4 = 24 hours. Units: hours.', 14),('8a4463b9-dc26-436e-8b02-e69271375f88'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'true_false', 'G1 phase of the cell cycle is primarily for cell growth and protein synthesis.', 'True', 'G1 is dedicated to growth and metabolic activities, including protein synthesis.', 15),('1f7caefa-c1ab-4ee8-8a6e-97217f246bf2'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'List the four main phases of the cell cycle in order.', 'G1, S, G2, M', 'The standard sequence of the cell cycle phases is G1 → S → G2 → M.', 16),('f16d3f32-2074-420e-86fc-f1251b529549'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'Explain why cell size is limited and how this leads to cell division.', 'Because as cells grow, their volume increases faster than their surface area, reducing the efficiency of material exchange; to maintain effective transport and metabolism, cells divide.', 'A cell''s surface area-to-volume ratio governs exchange with the environment. When growth reduces this ratio, division restores efficiency.', 17),('d023fcf6-0229-4439-8185-79f5b5869569'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'In metaphase of mitosis, a somatic cell has 2n=8 chromosomes. How many sister chromatids are aligned at the metaphase plate?', '16 chromatids', 'Metaphase aligns all chromosomes, each consisting of two sister chromatids: 8 chromosomes × 2 = 16 chromatids.', 18),('b9e53d2a-fd09-40e9-8a4c-f83d9abcabdf'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'In a mitotic cell with 2n=8 chromosomes, the S phase is extended from 7 hours to 14 hours due to replication stress. If the other phases durations remain G1=9 h, G2=4 h, M=4 h, what is the new total cell cycle length?', '31 hours', 'New total = G1 + S (extended) + G2 + M = 9 + 14 + 4 + 4 = 31 hours.', 19),('a67e0ae0-8030-4f5c-8abd-e19b2935b444'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'What is the main purpose of mitosis in cell reproduction?', 'To distribute identical copies of the genome to two daughter nuclei', 'Mitosis ensures each daughter nucleus receives an identical set of chromosomes, preserving genetic information.', 20),('d916e0bc-a243-4893-811f-f70dde1b8ee8'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which phase of the cell cycle is primarily associated with DNA replication?', 'S', 'S phase is when DNA replication occurs.', 21),('ce17a088-e79a-4fa4-826d-80f0b431d1c0'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'During which event in mitosis do sister chromatids separate and migrate toward opposite poles?', 'Anaphase', 'Anaphase separates sister chromatids to opposite poles.', 22),('ff1f6791-6ec4-454e-894f-71a1863ec133'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which cellular structure is primarily responsible for organizing spindle fibers during animal cell mitosis?', 'Centrosomes', 'Centrosomes organize spindle fibers; they contain a pair of centrioles in animal cells.', 23),('cb886b26-b6e9-42a9-87e8-cfb17f0c7922'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which protein complex is most directly involved in advancing the cell cycle from G2 into M phase by triggering mitosis?', 'Cyclin-CDK complexes', 'Cyclin-CDK complexes drive transitions into mitosis by phosphorylating key proteins.', 24),('8903ec31-c8f1-460b-8258-66f022c8ab3e'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'true_false', 'During prophase, the nuclear envelope breaks down.', 'True', 'The nuclear envelope breaks down in prophase to allow spindle–chromosome interactions.', 25),('6e7fb211-46e7-4bd6-88f9-0d7c8d36a709'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'List the six stages of mitosis in order.', 'Prophase, Prometaphase, Metaphase, Anaphase, Telophase, Cytokinesis', 'Mitosis progresses through these stages in sequence to divide genetic material, followed by cytokinesis for cytoplasm division.', 26),('f1de1452-3ec4-4699-85f9-8e15a5c58749'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'Describe two potential consequences of loss of cell cycle regulation in a tissue.', '1) Uncontrolled cell division leading to tumor formation; 2) Tissue dysfunction due to overcrowding and resource depletion.', 'Failing cell cycle controls can cause cancerous growth and disrupt normal tissue function due to crowding and competition for nutrients.', 27),('6549d2c5-0616-4821-868a-7aba8c26e4b0'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'In a diploid human cell with 46 chromosomes, how many chromosomes are present in each daughter cell after mitosis? Provide the answer with units and a brief method.', '46 chromosomes', 'Mitosis preserves the chromosome number; each daughter cell receives a full set of 46 chromosomes.', 28),('4e0da5df-1158-4306-8bc8-a5aac99408b6'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'If a cell has 46 chromosomes and DNA replication occurs during S phase, how many total chromatids are present immediately after replication and just before mitosis? Provide the answer with units and a brief method.', '92 chromatids', 'DNA replication doubles the chromatid count, so 46 chromosomes become 92 chromatids prior to mitosis.', 29),('c40b4ac9-073b-4844-89ef-ba0ea5791d9d'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'What are the two main divisions of the cell cycle?', 'Interphase and Mitotic (M) phase', 'The cell cycle is commonly described as Interphase (growth and DNA replication) and the Mitotic (M) phase (cell division).', 30),('75a509f4-0c2c-4e4e-83c0-f0c956102bc0'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which organelle houses most of the cell''s genetic material?', 'Nucleus', 'DNA is organized inside the nucleus in eukaryotic cells.', 31),('eca124bd-cfae-496a-8c5d-a414f1d2b5eb'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'true_false', 'DNA replication occurs during S phase of the cell cycle.', 'True', 'S phase is the part of the cell cycle where DNA replication occurs before mitosis.', 32),('6c39b407-07f9-4201-880c-b66f687e2dd0'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which process ensures genetic material is evenly distributed into two daughter nuclei during cell division?', 'Mitosis', 'Karyokinesis during mitosis distributes chromosomes into two nuclei.', 33),('c74656f4-2123-4566-8867-ddf8a0fa90ea'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'Which organelle is primarily involved in energy production and is often called the powerhouse of the cell?', 'Mitochondrion', 'Mitochondria generate ATP through cellular respiration.', 34),('23a4f904-da3f-442b-8b3d-57aa7ebf4cf7'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'In a hypothetical cell cycle, G1=8 h, S=6 h, G2=4 h, M=2 h. What is the total cycle duration in hours? Show steps and final unit.', '20 h', 'Total cycle duration = G1 + S + G2 + M = 8 + 6 + 4 + 2 = 20 hours.', 35),('c6e6b679-049e-4dd6-8e12-9b3ff8b032ae'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'multiple_choice', 'If the cell cycle is not properly regulated, which outcome is most likely?', 'Uncontrolled cell growth leading to cancer', 'Loss of regulatory checkpoints can lead to uncontrolled proliferation, potentially forming tumors or cancer.', 36),('0c49cdb5-1a26-492a-846f-983882636af2'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'Explain one cellular consequence of loss of cell cycle control.', 'Uncontrolled cell division can lead to tumor formation or cancer due to accumulation of mutations.', 'Checkpoints prevent progression with DNA damage; without control, cells may divide despite problems.', 37),('ca9305f9-e467-4e80-83d2-aa1ca010002d'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'In a second scenario, G1=6 h, S=10 h, G2=4 h, M=4 h. What is the total cycle duration in hours and what percent of the cycle does each phase occupy? Provide values and final unit.', 'Total cycle duration = 24 h; G1=25% (6/24), S=41.7% (10/24), G2=16.7% (4/24), M=16.7% (4/24).', 'Total = 6+10+4+4 = 24 hours. Percentages come from each phase duration divided by total.', 38),('3a050a85-bde3-4cf5-8acd-50469e5ce16e'::uuid, '0c5e50c7-fec1-43e9-8f05-61fa565f30d9'::uuid, 'fill_blank', 'How do cell cycle checkpoints contribute to maintaining genome integrity?', 'Checkpoints pause the cycle to allow DNA repair and ensure proper chromosome attachment; they prevent progression with damaged DNA.', 'Checkpoints monitor DNA integrity and spindle attachment, enabling repair before progression.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
